    #[doc = " Provides a shared context for creating translation units.\n\n It provides two options:\n\n - excludeDeclarationsFromPCH: When non-zero, allows enumeration of \"local\"\n declarations (when loading any new translation units). A \"local\" declaration\n is one that belongs in the translation unit itself and not in a precompiled\n header that was used by the translation unit. If zero, all declarations\n will be enumerated.\n\n Here is an example:\n\n \\code\n   // excludeDeclsFromPCH = 1, displayDiagnostics=1\n   Idx = clang_createIndex(1, 1);\n\n   // IndexTest.pch was produced with the following command:\n   // \"clang -x c IndexTest.h -emit-ast -o IndexTest.pch\"\n   TU = clang_createTranslationUnit(Idx, \"IndexTest.pch\");\n\n   // This will load all the symbols from 'IndexTest.pch'\n   clang_visitChildren(clang_getTranslationUnitCursor(TU),\n                       TranslationUnitVisitor, 0);\n   clang_disposeTranslationUnit(TU);\n\n   // This will load all the symbols from 'IndexTest.c', excluding symbols\n   // from 'IndexTest.pch'.\n   char *args[] = { \"-Xclang\", \"-include-pch=IndexTest.pch\" };\n   TU = clang_createTranslationUnitFromSourceFile(Idx, \"IndexTest.c\", 2, args,\n                                                  0, 0);\n   clang_visitChildren(clang_getTranslationUnitCursor(TU),\n                       TranslationUnitVisitor, 0);\n   clang_disposeTranslationUnit(TU);\n \\endcode\n\n This process of creating the 'pch', loading it separately, and using it (via\n -include-pch) allows 'excludeDeclsFromPCH' to remove redundant callbacks\n (which gives the indexer the same performance benefit as the compiler)."]
    pub fn clang_createIndex(
        excludeDeclarationsFromPCH: ::std::os::raw::c_int,
        displayDiagnostics: ::std::os::raw::c_int,
    ) -> CXIndex;
    #[doc = " Destroy the given index.\n\n The index must not be destroyed until all of the translation units created\n within that index have been destroyed."]
    pub fn clang_disposeIndex(index: CXIndex);
    #[doc = " Provides a shared context for creating translation units.\n\n Call this function instead of clang_createIndex() if you need to configure\n the additional options in CXIndexOptions.\n\n \\returns The created index or null in case of error, such as an unsupported\n value of options->Size.\n\n For example:\n \\code\n CXIndex createIndex(const char *ApplicationTemporaryPath) {\n   const int ExcludeDeclarationsFromPCH = 1;\n   const int DisplayDiagnostics = 1;\n   CXIndex Idx;\n #if CINDEX_VERSION_MINOR >= 64\n   CXIndexOptions Opts;\n   memset(&Opts, 0, sizeof(Opts));\n   Opts.Size = sizeof(CXIndexOptions);\n   Opts.ThreadBackgroundPriorityForIndexing = 1;\n   Opts.ExcludeDeclarationsFromPCH = ExcludeDeclarationsFromPCH;\n   Opts.DisplayDiagnostics = DisplayDiagnostics;\n   Opts.PreambleStoragePath = ApplicationTemporaryPath;\n   Idx = clang_createIndexWithOptions(&Opts);\n   if (Idx)\n     return Idx;\n   fprintf(stderr,\n           \"clang_createIndexWithOptions() failed. \"\n           \"CINDEX_VERSION_MINOR = %d, sizeof(CXIndexOptions) = %u\\n\",\n           CINDEX_VERSION_MINOR, Opts.Size);\n #else\n   (void)ApplicationTemporaryPath;\n #endif\n   Idx = clang_createIndex(ExcludeDeclarationsFromPCH, DisplayDiagnostics);\n   clang_CXIndex_setGlobalOptions(\n       Idx, clang_CXIndex_getGlobalOptions(Idx) |\n                CXGlobalOpt_ThreadBackgroundPriorityForIndexing);\n   return Idx;\n }\n \\endcode\n\n \\sa clang_createIndex()"]
    #[doc = ""]
    #[doc = " Only available on `libclang` 17.0 and later."]
    #[cfg(any(feature = "clang_17_0", not(feature = "clang_14_0")))]
    pub fn clang_createIndexWithOptions(options: *const CXIndexOptions) -> CXIndex;
    #[doc = " Sets general options associated with a CXIndex.\n\n This function is DEPRECATED. Set\n CXIndexOptions::ThreadBackgroundPriorityForIndexing and/or\n CXIndexOptions::ThreadBackgroundPriorityForEditing and call\n clang_createIndexWithOptions() instead.\n\n For example:\n \\code\n CXIndex idx = ...;\n clang_CXIndex_setGlobalOptions(idx,\n     clang_CXIndex_getGlobalOptions(idx) |\n     CXGlobalOpt_ThreadBackgroundPriorityForIndexing);\n \\endcode\n\n \\param options A bitmask of options, a bitwise OR of CXGlobalOpt_XXX flags."]
    pub fn clang_CXIndex_setGlobalOptions(arg1: CXIndex, options: ::std::os::raw::c_uint);
    #[doc = " Gets the general options associated with a CXIndex.\n\n This function allows to obtain the final option values used by libclang after\n specifying the option policies via CXChoice enumerators.\n\n \\returns A bitmask of options, a bitwise OR of CXGlobalOpt_XXX flags that\n are associated with the given CXIndex object."]
    pub fn clang_CXIndex_getGlobalOptions(arg1: CXIndex) -> ::std::os::raw::c_uint;
    #[doc = " Sets the invocation emission path option in a CXIndex.\n\n This function is DEPRECATED. Set CXIndexOptions::InvocationEmissionPath and\n call clang_createIndexWithOptions() instead.\n\n The invocation emission path specifies a path which will contain log\n files for certain libclang invocations. A null value (default) implies that\n libclang invocations are not logged.."]
