    pub fn clang_disposeTranslationUnit(arg1: CXTranslationUnit);
    #[doc = " Returns the set of flags that is suitable for reparsing a translation\n unit.\n\n The set of flags returned provide options for\n \\c clang_reparseTranslationUnit() by default. The returned flag\n set contains an unspecified set of optimizations geared toward common uses\n of reparsing. The set of optimizations enabled may change from one version\n to the next."]
    pub fn clang_defaultReparseOptions(TU: CXTranslationUnit) -> ::std::os::raw::c_uint;
    #[doc = " Reparse the source files that produced this translation unit.\n\n This routine can be used to re-parse the source files that originally\n created the given translation unit, for example because those source files\n have changed (either on disk or as passed via \\p unsaved_files). The\n source code will be reparsed with the same command-line options as it\n was originally parsed.\n\n Reparsing a translation unit invalidates all cursors and source locations\n that refer into that translation unit. This makes reparsing a translation\n unit semantically equivalent to destroying the translation unit and then\n creating a new translation unit with the same command-line arguments.\n However, it may be more efficient to reparse a translation\n unit using this routine.\n\n \\param TU The translation unit whose contents will be re-parsed. The\n translation unit must originally have been built with\n \\c clang_createTranslationUnitFromSourceFile().\n\n \\param num_unsaved_files The number of unsaved file entries in \\p\n unsaved_files.\n\n \\param unsaved_files The files that have not yet been saved to disk\n but may be required for parsing, including the contents of\n those files.  The contents and name of these files (as specified by\n CXUnsavedFile) are copied when necessary, so the client only needs to\n guarantee their validity until the call to this function returns.\n\n \\param options A bitset of options composed of the flags in CXReparse_Flags.\n The function \\c clang_defaultReparseOptions() produces a default set of\n options recommended for most uses, based on the translation unit.\n\n \\returns 0 if the sources could be reparsed.  A non-zero error code will be\n returned if reparsing was impossible, such that the translation unit is\n invalid. In such cases, the only valid call for \\c TU is\n \\c clang_disposeTranslationUnit(TU).  The error codes returned by this\n routine are described by the \\c CXErrorCode enum."]
    pub fn clang_reparseTranslationUnit(
        TU: CXTranslationUnit,
        num_unsaved_files: ::std::os::raw::c_uint,
        unsaved_files: *mut CXUnsavedFile,
        options: ::std::os::raw::c_uint,
    ) -> ::std::os::raw::c_int;
