    pub fn clang_getCursorVisibility(cursor: CXCursor) -> CXVisibilityKind;
    #[doc = " Determine the availability of the entity that this cursor refers to,\n taking the current target platform into account.\n\n \\param cursor The cursor to query.\n\n \\returns The availability of the cursor."]
    pub fn clang_getCursorAvailability(cursor: CXCursor) -> CXAvailabilityKind;
    #[doc = " Determine the availability of the entity that this cursor refers to\n on any platforms for which availability information is known.\n\n \\param cursor The cursor to query.\n\n \\param always_deprecated If non-NULL, will be set to indicate whether the\n entity is deprecated on all platforms.\n\n \\param deprecated_message If non-NULL, will be set to the message text\n provided along with the unconditional deprecation of this entity. The client\n is responsible for deallocating this string.\n\n \\param always_unavailable If non-NULL, will be set to indicate whether the\n entity is unavailable on all platforms.\n\n \\param unavailable_message If non-NULL, will be set to the message text\n provided along with the unconditional unavailability of this entity. The\n client is responsible for deallocating this string.\n\n \\param availability If non-NULL, an array of CXPlatformAvailability instances\n that will be populated with platform availability information, up to either\n the number of platforms for which availability information is available (as\n returned by this function) or \\c availability_size, whichever is smaller.\n\n \\param availability_size The number of elements available in the\n \\c availability array.\n\n \\returns The number of platforms (N) for which availability information is\n available (which is unrelated to \\c availability_size).\n\n Note that the client is responsible for calling\n \\c clang_disposeCXPlatformAvailability to free each of the\n platform-availability structures returned. There are\n \\c min(N, availability_size) such structures."]
    pub fn clang_getCursorPlatformAvailability(
        cursor: CXCursor,
        always_deprecated: *mut ::std::os::raw::c_int,
        deprecated_message: *mut CXString,
        always_unavailable: *mut ::std::os::raw::c_int,
        unavailable_message: *mut CXString,
        availability: *mut CXPlatformAvailability,
        availability_size: ::std::os::raw::c_int,
    ) -> ::std::os::raw::c_int;
    #[doc = " Free the memory associated with a \\c CXPlatformAvailability structure."]
    pub fn clang_disposeCXPlatformAvailability(availability: *mut CXPlatformAvailability);
