    pub fn clang_Cursor_getNumArguments(C: CXCursor) -> ::std::os::raw::c_int;
    #[doc = " Retrieve the argument cursor of a function or method.\n\n The argument cursor can be determined for calls as well as for declarations\n of functions or methods. For other cursors and for invalid indices, an\n invalid cursor is returned."]
    pub fn clang_Cursor_getArgument(C: CXCursor, i: ::std::os::raw::c_uint) -> CXCursor;
    #[doc = " Returns the number of template args of a function, struct, or class decl\n representing a template specialization.\n\n If the argument cursor cannot be converted into a template function\n declaration, -1 is returned.\n\n For example, for the following declaration and specialization:\n   template <typename T, int kInt, bool kBool>\n   void foo() { ... }\n\n   template <>\n   void foo<float, -7, true>();\n\n The value 3 would be returned from this call."]
    pub fn clang_Cursor_getNumTemplateArguments(C: CXCursor) -> ::std::os::raw::c_int;
    #[doc = " Retrieve the kind of the I'th template argument of the CXCursor C.\n\n If the argument CXCursor does not represent a FunctionDecl, StructDecl, or\n ClassTemplatePartialSpecialization, an invalid template argument kind is\n returned.\n\n For example, for the following declaration and specialization:\n   template <typename T, int kInt, bool kBool>\n   void foo() { ... }\n\n   template <>\n   void foo<float, -7, true>();\n\n For I = 0, 1, and 2, Type, Integral, and Integral will be returned,\n respectively."]
    pub fn clang_Cursor_getTemplateArgumentKind(
        C: CXCursor,
        I: ::std::os::raw::c_uint,
    ) -> CXTemplateArgumentKind;
    #[doc = " Retrieve a CXType representing the type of a TemplateArgument of a\n  function decl representing a template specialization.\n\n If the argument CXCursor does not represent a FunctionDecl, StructDecl,\n ClassDecl or ClassTemplatePartialSpecialization whose I'th template argument\n has a kind of CXTemplateArgKind_Integral, an invalid type is returned.\n\n For example, for the following declaration and specialization:\n   template <typename T, int kInt, bool kBool>\n   void foo() { ... }\n\n   template <>\n   void foo<float, -7, true>();\n\n If called with I = 0, \"float\", will be returned.\n Invalid types will be returned for I == 1 or 2."]
    pub fn clang_Cursor_getTemplateArgumentType(C: CXCursor, I: ::std::os::raw::c_uint) -> CXType;
    #[doc = " Retrieve the value of an Integral TemplateArgument (of a function\n  decl representing a template specialization) as a signed long long.\n\n It is undefined to call this function on a CXCursor that does not represent a\n FunctionDecl, StructDecl, ClassDecl or ClassTemplatePartialSpecialization\n whose I'th template argument is not an integral value.\n\n For example, for the following declaration and specialization:\n   template <typename T, int kInt, bool kBool>\n   void foo() { ... }\n\n   template <>\n   void foo<float, -7, true>();\n\n If called with I = 1 or 2, -7 or true will be returned, respectively.\n For I == 0, this function's behavior is undefined."]
    pub fn clang_Cursor_getTemplateArgumentValue(
        C: CXCursor,
        I: ::std::os::raw::c_uint,
    ) -> ::std::os::raw::c_longlong;
    #[doc = " Retrieve the value of an Integral TemplateArgument (of a function\n  decl representing a template specialization) as an unsigned long long.\n\n It is undefined to call this function on a CXCursor that does not represent a\n FunctionDecl, StructDecl, ClassDecl or ClassTemplatePartialSpecialization or\n whose I'th template argument is not an integral value.\n\n For example, for the following declaration and specialization:\n   template <typename T, int kInt, bool kBool>\n   void foo() { ... }\n\n   template <>\n   void foo<float, 2147483649, true>();\n\n If called with I = 1 or 2, 2147483649 or true will be returned, respectively.\n For I == 0, this function's behavior is undefined."]
    pub fn clang_Cursor_getTemplateArgumentUnsignedValue(
        C: CXCursor,
        I: ::std::os::raw::c_uint,
    ) -> ::std::os::raw::c_ulonglong;
    #[doc = " Determine whether two CXTypes represent the same type.\n\n \\returns non-zero if the CXTypes represent the same type and\n          zero otherwise."]
    pub fn clang_equalTypes(A: CXType, B: CXType) -> ::std::os::raw::c_uint;
    #[doc = " Return the canonical type for a CXType.\n\n Clang's type system explicitly models typedefs and all the ways\n a specific type can be represented.  The canonical type is the underlying\n type with all the \"sugar\" removed.  For example, if 'T' is a typedef\n for 'int', the canonical type for 'T' would be 'int'."]
    pub fn clang_getCanonicalType(T: CXType) -> CXType;
