    #[doc = " Determine whether a  CXCursor that is a macro, is a\n builtin one."]
    pub fn clang_Cursor_isMacroBuiltin(C: CXCursor) -> ::std::os::raw::c_uint;
    #[doc = " Determine whether a  CXCursor that is a function declaration, is an\n inline declaration."]
    pub fn clang_Cursor_isFunctionInlined(C: CXCursor) -> ::std::os::raw::c_uint;
    #[doc = " Determine whether a CXType has the \"volatile\" qualifier set,\n without looking through typedefs that may have added \"volatile\" at\n a different level."]
    pub fn clang_isVolatileQualifiedType(T: CXType) -> ::std::os::raw::c_uint;
    #[doc = " Determine whether a CXType has the \"restrict\" qualifier set,\n without looking through typedefs that may have added \"restrict\" at a\n different level."]
    pub fn clang_isRestrictQualifiedType(T: CXType) -> ::std::os::raw::c_uint;
