    #[doc = " Determines if a C++ constructor or conversion function was declared\n explicit, returning 1 if such is the case and 0 otherwise.\n\n Constructors or conversion functions are declared explicit through\n the use of the explicit specifier.\n\n For example, the following constructor and conversion function are\n not explicit as they lack the explicit specifier:\n\n     class Foo {\n         Foo();\n         operator int();\n     };\n\n While the following constructor and conversion function are\n explicit as they are declared with the explicit specifier.\n\n     class Foo {\n         explicit Foo();\n         explicit operator int();\n     };\n\n This function will return 0 when given a cursor pointing to one of\n the former declarations and it will return 1 for a cursor pointing\n to the latter declarations.\n\n The explicit specifier allows the user to specify a\n conditional compile-time expression whose value decides\n whether the marked element is explicit or not.\n\n For example:\n\n     constexpr bool foo(int i) { return i % 2 == 0; }\n\n     class Foo {\n          explicit(foo(1)) Foo();\n          explicit(foo(2)) operator int();\n     }\n\n This function will return 0 for the constructor and 1 for\n the conversion function."]
    #[doc = ""]
    #[doc = " Only available on `libclang` 17.0 and later."]
    #[cfg(any(feature = "clang_17_0", not(feature = "clang_14_0")))]
    pub fn clang_CXXMethod_isExplicit(C: CXCursor) -> ::std::os::raw::c_uint;
